import { afterEach, beforeEach, expect, rs, test } from "@rstest/core";
import {
  act,
  cleanup,
  fireEvent,
  render,
  screen,
  waitFor,
} from "@testing-library/react";
import { createI18n } from "delino-i18n/react";
import registry from "../i18n/locales.json";
import source from "../i18n/messages/en.json";
import { AuthContextProvider, NOT_CONFIGURED } from "./auth.tsx";
import { TopBar } from "./components/shell.tsx";
import { I18nProvider } from "./i18n.ts";
import { RouterProvider } from "./router.tsx";

// The target catalogs are generated by the translation tool, so the test
// replaces the app's i18n module with a provider of the same registry, source
// catalog and storage key whose `load` returns a small fake catalog. The
// factory runs when `./i18n.ts` is first imported, after the imports above.
rs.mock("./i18n.ts", () =>
  createI18n({
    registry,
    source,
    storageKey: "delino.language",
    load: async (lang) =>
      lang === "ko"
        ? { "common.language": "언어", "nav.billing": "결제" }
        : Promise.reject(new Error(`no catalog for ${lang}`)),
  }),
);

beforeEach(() => {
  window.localStorage.clear();
  window.history.replaceState(null, "", "/");
});

afterEach(() => {
  cleanup();
  window.localStorage.clear();
  document.documentElement.lang = "en";
});

function renderTopBar() {
  render(
    <I18nProvider initial={{ lang: "en", messages: source }}>
      <AuthContextProvider value={NOT_CONFIGURED}>
        <RouterProvider>
          <TopBar />
        </RouterProvider>
      </AuthContextProvider>
    </I18nProvider>,
  );
}

async function click(element: Element) {
  await act(async () => {
    fireEvent.click(element);
  });
}

test("the language menu of the top bar switches the language and keeps it", async () => {
  renderTopBar();
  expect(screen.getByRole("link", { name: "Billing" })).toBeTruthy();

  await click(screen.getByRole("combobox", { name: "Language" }));
  const korean = await screen.findByRole("option", { name: "한국어" });
  // Each language is listed by its native label in its own language.
  expect(korean.getAttribute("lang")).toBe("ko");
  expect(screen.getByRole("option", { name: "English" })).toBeTruthy();
  await click(korean);

  await waitFor(() =>
    expect(screen.getByRole("link", { name: "결제" })).toBeTruthy(),
  );
  expect(screen.queryByRole("link", { name: "Billing" })).toBeNull();
  expect(screen.getByRole("combobox", { name: "언어" })).toBeTruthy();
  expect(window.localStorage.getItem("delino.language")).toBe("ko");
  expect(document.documentElement.lang).toBe("ko");
});

test("a language whose catalog cannot load keeps the current language", async () => {
  const errors: unknown[][] = [];
  const spy = rs
    .spyOn(console, "error")
    .mockImplementation((...args: unknown[]) => {
      errors.push(args);
    });
  try {
    renderTopBar();
    await click(screen.getByRole("combobox", { name: "Language" }));
    await click(await screen.findByRole("option", { name: "日本語" }));

    await waitFor(() =>
      expect(
        errors.some(([event]) => event === "language_selection_failed"),
      ).toBe(true),
    );
    expect(screen.getByRole("link", { name: "Billing" })).toBeTruthy();
    expect(window.localStorage.getItem("delino.language")).toBeNull();
  } finally {
    spy.mockRestore();
  }
});
